#!/usr/bin/env node
/**
 * Build both halves of the plugin.
 *
 * Host half: one ESM bundle for Node with every `@deepseek-ai/*` package left
 * external, so the running installation supplies its own instances (Cordis in
 * particular must be a single instance per profile). The P0 contract
 * assertions are unchanged.
 *
 * Browser half: the DSH client module system is a lazy CommonJS table — a
 * classic script calls `window.__ModuleLoader__.load({ id, factory })` and the
 * factory receives a synchronous `require` over the shell's frozen module
 * table. So the client build is CommonJS, keeps every platform module as a bare
 * `require(...)`, inlines everything else, and is then wrapped in that
 * registration. This reproduces the proven `dsh-highlights` pipeline (the
 * repo's own client preset is not a published package).
 *
 * Determinism: no timestamps, no generated banner, stable input order; an
 * unchanged source tree produces byte-identical artifacts.
 *
 * Usage: node scripts/build.mjs
 */
import { build } from 'esbuild'
import { access, readFile, rename, rm, mkdir, writeFile } from 'node:fs/promises'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const PACKAGE_NAME = 'dsh-open-items'
const OUT = join(ROOT, 'lib')
const HOST_OUT = join(OUT, 'index.js')

/** Host-half externals: resolved by Node from the profile/installation. */
const HOST_EXTERNALS = ['@deepseek-ai/*']

/**
 * Modules the shell's module table provides to every plugin bundle.
 * Mirrors `PLATFORM_MODULES` in `packages/client/web/src/platform.ts` (rc.1).
 * These are the only specifiers a client bundle may require.
 */
const PLATFORM_MODULES = [
  'react',
  'react/jsx-runtime',
  'react-dom',
  'react-dom/client',
  '@deepseek-ai/cordis',
  'zod',
  '@tanstack/react-virtual',
  '@deepseek-ai/dsh-client-store',
  '@deepseek-ai/dsh-client-ui-slots',
  '@deepseek-ai/dsh-client-ui-primitives',
  '@deepseek-ai/dsh-client-ui-dockkit',
]

/** Client-bundle ceiling in KiB; the milestone gate fails the build above it. */
const CLIENT_BUNDLE_BUDGET_KIB = 400

/** Wrap one CommonJS client bundle in the module-loader registration. */
function wrapClientBundle(body) {
  return [
    `/* ${PACKAGE_NAME} client bundle — generated by scripts/build.mjs; do not edit. */`,
    'window.__ModuleLoader__.load({',
    `  id: ${JSON.stringify(PACKAGE_NAME)},`,
    '  factory: (require) => {',
    '    var module = { exports: {} };',
    '    var exports = module.exports;',
    body,
    '    return module.exports;',
    '  },',
    '});',
    '',
  ].join('\n')
}

/** Errors accumulated by one assertion pass. */
class Failures {
  /** @type {string[]} */
  list = []
  /**
   * @param {boolean} condition - whether the claim holds.
   * @param {string} message - failure description.
   */
  check(condition, message) {
    if (!condition) this.list.push(message)
  }
}

/**
 * Assert the host bundle contract (unchanged from the P0 milestone).
 * @param source - built host module source.
 */
function assertHostContract(source) {
  const failures = new Failures()
  failures.check(source.includes(PACKAGE_NAME), 'host bundle does not mention the package name')
  failures.check(/export\s*\{[^}]*\bapply\b/u.test(source), 'host bundle does not export apply')
  failures.check(/export\s*\{[^}]*\binject\b/u.test(source), 'host bundle does not export inject')
  failures.check(/from\s+["']@deepseek-ai\/cordis["']/u.test(source), 'host bundle does not import @deepseek-ai/cordis as an external')
  failures.check(!source.includes('node_modules/@deepseek-ai/cordis'), 'host bundle inlined @deepseek-ai/cordis; it must stay external')
  failures.check(source.includes('cordis.patch.yml') || source.includes('open-items'), 'host bundle does not look like the open-items plugin')
  // Session-log policy (docs/session-log-policy.md): out-of-tree plugins must
  // not append non-ignorable events; the store is the only audit trail.
  failures.check(!source.includes('session.append'), 'host bundle contains a Session-log write path; out-of-tree plugins must not append events')
  failures.check(!source.includes('appendPluginRecord'), 'host bundle calls appendPluginRecord; see docs/session-log-policy.md')
  failures.check(!source.includes('SessionEventMap'), 'host bundle declares non-ignorable Session event types; see docs/session-log-policy.md')
  failures.check(!source.includes('open-items/raised'), 'host bundle declares a non-ignorable Session event literal')
  return failures.list
}

/**
 * Assert the browser bundle contract: module-loader registration, CommonJS
 * factory, platform-only requires, React externalised, no Node builtins.
 * @param source - wrapped client bundle source.
 */
function assertClientContract(source) {
  const failures = new Failures()
  failures.check(source.includes('window.__ModuleLoader__.load('), 'client bundle is not module-loader wrapped')
  failures.check(source.includes(`id: ${JSON.stringify(PACKAGE_NAME)}`), 'client bundle registers under the wrong package id')
  failures.check(/factory:\s*\(require\)\s*=>/u.test(source), 'client bundle factory does not receive the module table require')
  failures.check(source.includes('module.exports'), 'client bundle does not expose the CommonJS module exports')
  const requires = [...source.matchAll(/require\(\s*["']([^"']+)["']\s*\)/gu)].map(match => match[1])
  const unexpected = [...new Set(requires.filter(id => !PLATFORM_MODULES.includes(id)))]
  failures.check(unexpected.length === 0, `client bundle requires modules outside the platform table: ${unexpected.join(', ')}`)
  failures.check(requires.includes('react'), 'client bundle never requires "react"; React must stay external')
  failures.check(requires.includes('react/jsx-runtime'), 'client bundle never requires "react/jsx-runtime"; the JSX transform is not externalised')
  failures.check(!/(?:require\(\s*["']node:|from\s+["']node:)/u.test(source), 'client bundle imports a Node builtin; the browser half must have no node: imports')
  failures.check(!source.includes('node_modules/react/'), 'client bundle inlined React; it must stay external')
  failures.check(!source.includes('react.development.js'), 'client bundle inlined a React development build')
  failures.check(!source.includes('@deepseek-ai/dsh-client-ui-frontend'), 'client bundle references an in-tree-only module')
  const bytes = Buffer.byteLength(source, 'utf8')
  failures.check(bytes / 1024 <= CLIENT_BUNDLE_BUDGET_KIB, `client bundle ${(bytes / 1024).toFixed(1)} KiB exceeds the ${CLIENT_BUNDLE_BUDGET_KIB} KiB budget`)
  return { failures: failures.list, bytes }
}

/**
 * Build the host half.
 * @returns the built source length in KiB.
 */
async function buildHost() {
  await build({
    entryPoints: [join(ROOT, 'src/host/index.ts')],
    outfile: HOST_OUT,
    bundle: true,
    format: 'esm',
    platform: 'node',
    target: 'node24',
    sourcemap: true,
    external: HOST_EXTERNALS,
    logLevel: 'info',
  })
  await access(HOST_OUT)
  const source = await readFile(HOST_OUT, 'utf8')
  const failures = assertHostContract(source)
  if (failures.length > 0) throw new Error(`host contract FAILED:\n  - ${failures.join('\n  - ')}`)
  return Buffer.byteLength(source, 'utf8') / 1024
}

/**
 * Build and wrap the browser half.
 * @returns the wrapped bundle size in KiB.
 */
async function buildClient() {
  await mkdir(OUT, { recursive: true })
  const raw = join(OUT, 'client.raw.cjs')
  await build({
    entryPoints: [join(ROOT, 'src/client/index.ts')],
    outfile: raw,
    bundle: true,
    format: 'cjs',
    platform: 'browser',
    target: 'es2022',
    jsx: 'automatic',
    minify: true,
    sourcemap: 'external',
    external: PLATFORM_MODULES,
    define: { 'process.env.NODE_ENV': '"production"' },
    logLevel: 'info',
  })
  const body = (await readFile(raw, 'utf8')).replace(/^\/\/# sourceMappingURL=.*$/mu, '')
  const wrapped = `${wrapClientBundle(body)}//# sourceMappingURL=client.js.map\n`
  const { failures, bytes } = assertClientContract(wrapped)
  if (failures.length > 0) throw new Error(`client contract FAILED:\n  - ${failures.join('\n  - ')}`)
  await rename(join(OUT, 'client.raw.cjs.map'), join(OUT, 'client.js.map'))
  await writeFile(join(OUT, 'client.js'), wrapped, 'utf8')
  await rm(raw, { force: true })
  await access(join(OUT, 'client.js.map'))
  return bytes / 1024
}

const hostKib = await buildHost()
const clientKib = await buildClient()
console.log(`host bundle: ${hostKib.toFixed(1)} KiB, contract OK`)
console.log(`client bundle: ${clientKib.toFixed(1)} KiB (budget ${CLIENT_BUNDLE_BUDGET_KIB} KiB), module-table contract OK`)
